d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

out = G['Demo pair 1 output']
inp = G['Demo pair 1 input']

# Let's try counting neighbors for each cell and see if that matches output
def count_neighbors(grid, i, j, include_self=True):
    neighbors = []
    if include_self:
        neighbors.append(grid[i][j])
    rows = len(grid)
    cols = len(grid[0])
    for di in range(-1, 2):
        for dj in range(-1, 2):
            if di == 0 and dj == 0:
                continue
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                neighbors.append(grid[ni][nj])
    return sum(neighbors), len(neighbors), max(neighbors), min(neighbors), set(neighbors)

print("Testing neighbor-based patterns:")
for i in range(4):
    for j in range(4):
        total, n, mx, mn, unique = count_neighbors(inp, i, j)
        test_r = i * 3 + 1
        test_c = j * 2
        actual = out[test_r][test_c] if 0 <= test_r < len(out) and 0 <= test_c < len(out[0]) else None
        print(f"inp[{i},{j}]={inp[i][j]} -> sum={total}, mx={mx}, unique={unique} -> out[{test_r},{test_c}]={actual}")

